import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

// Create axios instance with auth header
const api = axios.create({
  baseURL: "http://localhost:8000",
});

// Add interceptor to include token in requests
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

function ManagerDashboard() {
  const navigate = useNavigate();
  const [profile, setProfile] = useState(null);
  const [teamOverview, setTeamOverview] = useState([]);
  const [pendingBills, setPendingBills] = useState([]);
  const [allBills, setAllBills] = useState([]);
  const [statistics, setStatistics] = useState({});
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('overview');
  const [message, setMessage] = useState("");
  const [selectedEmployee, setSelectedEmployee] = useState(null);
  const [employeeBills, setEmployeeBills] = useState([]);

  // Check authentication on component mount
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      navigate("/login");
      return;
    }
    
    fetchProfile();
    fetchData();
  }, [navigate]);

  const fetchProfile = async () => {
    try {
      const res = await api.get("/profile");
      setProfile(res.data);
      
      // Check if user is manager
      if (res.data.role !== 'manager') {
        navigate("/upload-bill"); // Redirect employees to upload page
      }
    } catch (err) {
      console.error("Error fetching profile:", err);
      if (err.response?.status === 401) {
        localStorage.removeItem("token");
        navigate("/login");
      }
    }
  };

  const fetchData = async () => {
    setLoading(true);
    try {
      await Promise.all([
        fetchTeamOverview(),
        fetchPendingBills(),
        fetchStatistics()
      ]);
    } catch (err) {
      console.error("Error fetching data:", err);
    } finally {
      setLoading(false);
    }
  };

  const fetchTeamOverview = async () => {
    try {
      const res = await api.get("/manager/team-overview");
      setTeamOverview(res.data || []);
    } catch (err) {
      console.error("Error fetching team overview:", err);
    }
  };

  const fetchPendingBills = async () => {
    try {
      const res = await api.get("/manager/pending-bills?page=1&page_size=20");
      setPendingBills(res.data.bills || []);
    } catch (err) {
      console.error("Error fetching pending bills:", err);
    }
  };

  const fetchAllBills = async () => {
    try {
      const res = await api.get("/bills/team-bills?page=1&page_size=50");
      setAllBills(res.data.bills || []);
    } catch (err) {
      console.error("Error fetching all bills:", err);
    }
  };

  const fetchStatistics = async () => {
    try {
      const res = await api.get("/manager/statistics");
      setStatistics(res.data || {});
    } catch (err) {
      console.error("Error fetching statistics:", err);
    }
  };

  const fetchEmployeeBills = async (employeeId) => {
    try {
      const res = await api.get(`/manager/employee-bills/${employeeId}`);
      setEmployeeBills(res.data || []);
    } catch (err) {
      console.error("Error fetching employee bills:", err);
    }
  };

  const handleEmployeeClick = (employee) => {
    setSelectedEmployee(employee);
    fetchEmployeeBills(employee.id);
  };

  const handleTabChange = (tab) => {
    setActiveTab(tab);
    if (tab === 'all-bills') {
      fetchAllBills();
    }
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(amount || 0);
  };

  const getStatusColor = (status) => {
    switch (status?.toLowerCase()) {
      case 'approved': return 'success';
      case 'pending': return 'warning';
      case 'rejected': return 'danger';
      default: return 'info';
    }
  };

  if (loading) {
    return (
      <div className="modern-manager-container">
        <div className="manager-header-section">
          <h1 className="manager-title">Manager Dashboard</h1>
          <p className="manager-subtitle">Manage your team and review expense submissions</p>
        </div>
        <div className="modern-loading-container">
          <div className="modern-loading-spinner">
            <div className="spinner-ring"></div>
            <div className="spinner-text">Loading dashboard...</div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="modern-manager-container">
      {/* Header Section */}
      <div className="manager-header-section">
        <div className="header-content">
          <h1 className="manager-title">Manager Dashboard</h1>
          <p className="manager-subtitle">Manage your team and review expense submissions</p>
        </div>
        {profile && (
          <div className="manager-info">
            <div className="manager-avatar">
              {profile.name ? profile.name.charAt(0).toUpperCase() : 'M'}
            </div>
            <div className="manager-details">
              <h3 className="manager-name">{profile.name || 'Manager'}</h3>
              <p className="manager-role">{profile.designation || 'Team Manager'}</p>
            </div>
          </div>
        )}
      </div>

      {/* Statistics Overview */}
      <div className="stats-section">
        <h2 className="section-title">Team Overview</h2>
        <div className="stats-grid">
          <div className="stat-card">
            <div className="stat-icon">👥</div>
            <div className="stat-content">
              <h3 className="stat-label">Team Members</h3>
              <p className="stat-value">{statistics.team_size || 0}</p>
            </div>
          </div>
          
          <div className="stat-card">
            <div className="stat-icon">📊</div>
            <div className="stat-content">
              <h3 className="stat-label">Total Expenses</h3>
              <p className="stat-value">{formatCurrency(statistics.total_expenses)}</p>
            </div>
          </div>
          
          <div className="stat-card">
            <div className="stat-icon">⏳</div>
            <div className="stat-content">
              <h3 className="stat-label">Pending Approvals</h3>
              <p className="stat-value">{statistics.pending_approvals || 0}</p>
            </div>
          </div>
          
          <div className="stat-card">
            <div className="stat-icon">✅</div>
            <div className="stat-content">
              <h3 className="stat-label">Approved This Month</h3>
              <p className="stat-value">{formatCurrency(statistics.monthly_approved)}</p>
            </div>
          </div>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="dashboard-tabs">
        <button 
          className={`tab-button ${activeTab === 'overview' ? 'active' : ''}`}
          onClick={() => handleTabChange('overview')}
        >
          <span className="tab-icon">📊</span>
          <span className="tab-text">Team Overview</span>
        </button>
        
        <button 
          className={`tab-button ${activeTab === 'pending' ? 'active' : ''}`}
          onClick={() => handleTabChange('pending')}
        >
          <span className="tab-icon">⏳</span>
          <span className="tab-text">Pending Approvals</span>
        </button>
        
        <button 
          className={`tab-button ${activeTab === 'all-bills' ? 'active' : ''}`}
          onClick={() => handleTabChange('all-bills')}
        >
          <span className="tab-icon">📋</span>
          <span className="tab-text">All Bills</span>
        </button>
      </div>

      {/* Tab Content */}
      <div className="tab-content">
        {/* Team Overview Tab */}
        {activeTab === 'overview' && (
          <div className="team-overview-section">
            <div className="team-grid">
              {teamOverview.map((employee) => (
                <div 
                  key={employee.id} 
                  className="employee-card"
                  onClick={() => handleEmployeeClick(employee)}
                >
                  <div className="employee-avatar">
                    {employee.name ? employee.name.charAt(0).toUpperCase() : 'E'}
                  </div>
                  <div className="employee-info">
                    <h3 className="employee-name">{employee.name}</h3>
                    <p className="employee-designation">{employee.designation}</p>
                    <p className="employee-email">{employee.email}</p>
                  </div>
                  <div className="employee-stats">
                    <div className="stat-item">
                      <span className="stat-number">{employee.total_bills || 0}</span>
                      <span className="stat-label">Bills</span>
                    </div>
                    <div className="stat-item">
                      <span className="stat-number">{formatCurrency(employee.total_expenses)}</span>
                      <span className="stat-label">Total</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Pending Approvals Tab */}
        {activeTab === 'pending' && (
          <div className="pending-bills-section">
            <div className="bills-grid">
              {pendingBills.map((bill) => (
                <div key={bill.id} className="bill-card pending">
                  <div className="bill-header">
                    <div className="bill-employee">
                      <span className="employee-initial">
                        {bill.employee_name ? bill.employee_name.charAt(0).toUpperCase() : 'E'}
                      </span>
                      <div className="employee-details">
                        <h4 className="employee-name">{bill.employee_name}</h4>
                        <p className="employee-designation">{bill.employee_designation}</p>
                      </div>
                    </div>
                    <span className={`status-badge ${getStatusColor(bill.status)}`}>
                      {bill.status}
                    </span>
                  </div>
                  
                  <div className="bill-content">
                    <div className="bill-amount">
                      <span className="amount-label">Amount:</span>
                      <span className="amount-value">{formatCurrency(bill.amount)}</span>
                    </div>
                    <div className="bill-details">
                      <p className="bill-description">{bill.description || 'No description'}</p>
                      <p className="bill-date">Submitted: {new Date(bill.created_at).toLocaleDateString()}</p>
                    </div>
                  </div>
                  
                  <div className="bill-actions">
                    <button className="action-btn approve">Approve</button>
                    <button className="action-btn reject">Reject</button>
                    <button className="action-btn view">View Details</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* All Bills Tab */}
        {activeTab === 'all-bills' && (
          <div className="all-bills-section">
            <div className="bills-grid">
              {allBills.map((bill) => (
                <div key={bill.id} className={`bill-card ${getStatusColor(bill.status)}`}>
                  <div className="bill-header">
                    <div className="bill-employee">
                      <span className="employee-initial">
                        {bill.employee_name ? bill.employee_name.charAt(0).toUpperCase() : 'E'}
                      </span>
                      <div className="employee-details">
                        <h4 className="employee-name">{bill.employee_name}</h4>
                        <p className="employee-designation">{bill.employee_designation}</p>
                      </div>
                    </div>
                    <span className={`status-badge ${getStatusColor(bill.status)}`}>
                      {bill.status}
                    </span>
                  </div>
                  
                  <div className="bill-content">
                    <div className="bill-amount">
                      <span className="amount-label">Amount:</span>
                      <span className="amount-value">{formatCurrency(bill.amount)}</span>
                    </div>
                    <div className="bill-details">
                      <p className="bill-description">{bill.description || 'No description'}</p>
                      <p className="bill-date">Submitted: {new Date(bill.created_at).toLocaleDateString()}</p>
                    </div>
                  </div>
                  
                  <div className="bill-actions">
                    <button className="action-btn view">View Details</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Employee Details Modal */}
      {selectedEmployee && (
        <div className="modal-overlay" onClick={() => setSelectedEmployee(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3 className="modal-title">{selectedEmployee.name}'s Details</h3>
              <button className="modal-close" onClick={() => setSelectedEmployee(null)}>✕</button>
            </div>
            
            <div className="modal-body">
              <div className="employee-detail-info">
                <div className="detail-row">
                  <span className="detail-label">Designation:</span>
                  <span className="detail-value">{selectedEmployee.designation}</span>
                </div>
                <div className="detail-row">
                  <span className="detail-label">Email:</span>
                  <span className="detail-value">{selectedEmployee.email}</span>
                </div>
                <div className="detail-row">
                  <span className="detail-label">Total Bills:</span>
                  <span className="detail-value">{selectedEmployee.total_bills || 0}</span>
                </div>
                <div className="detail-row">
                  <span className="detail-label">Total Expenses:</span>
                  <span className="detail-value">{formatCurrency(selectedEmployee.total_expenses)}</span>
                </div>
              </div>
              
              <div className="employee-bills-list">
                <h4 className="bills-title">Recent Bills</h4>
                {employeeBills.map((bill) => (
                  <div key={bill.id} className="bill-item">
                    <div className="bill-info">
                      <span className="bill-amount">{formatCurrency(bill.amount)}</span>
                      <span className="bill-date">{new Date(bill.created_at).toLocaleDateString()}</span>
                    </div>
                    <span className={`bill-status ${getStatusColor(bill.status)}`}>
                      {bill.status}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Message Display */}
      {message && (
        <div className="modern-message success">
          <div className="message-content">
            <span className="message-icon">✅</span>
            <span className="message-text">{message}</span>
          </div>
        </div>
      )}
    </div>
  );
}

export default ManagerDashboard;
